mkdir -p /tmp/claude-0/-home-user-Claudinite/44ea40a1-06be-535d-8a77-5f2bbcddfa73/scratchpad && cat > /tmp/claude-0/-home-user-Claudinite/44ea40a1-06be-535d-8a77-5f2bbcddfa73/scratchpad/vacuous.mjs <<'EOF'
// Find test bodies where EVERY assertion sits inside a loop or an `if` —
// so an empty/never-matching set passes the test vacuously.
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';

const files = execSync("git ls-files '*.test.mjs'", { cwd: '/home/user/Claudinite' })
  .toString().trim().split('\n');

const OPENERS = /^\s*(for\s*\(|while\s*\(|if\s*\(|\}?\s*else\b)/;
const FOREACH = /\.(forEach|map|filter|some|every|flatMap)\s*\(/;

for (const f of files) {
  const src = readFileSync('/home/user/Claudinite/' + f, 'utf8');
  const lines = src.split('\n');
  let block = null;
  for (let i = 0; i < lines.length; i++) {
    const L = lines[i];
    if (!block) {
      const m = L.match(/^(\s*)(?:await\s+)?(?:test|it)\(\s*(['"`])(.+?)\2/);
      if (m) block = { name: m[3], start: i, depth: 0, guards: [], top: 0, guarded: 0, lines: [] };
      if (!block) continue;
    }
    if (block) {
      block.lines.push(L);
      // count assertions before updating depth for this line
      const isAssert = /\bassert\b/.test(L) && !/^\s*(\/\/|\*)/.test(L);
      const inGuard = block.guards.length > 0;
      if (isAssert && i > block.start) { if (inGuard) block.guarded++; else block.top++; }
      // depth bookkeeping
      const opens = (L.match(/[{(]/g) || []).length;
      const closes = (L.match(/[})]/g) || []).length;
      const before = block.depth;
      if (OPENERS.test(L) || FOREACH.test(L)) {
        if (opens > closes) block.guards.push(before);
      }
      block.depth += opens - closes;
      while (block.guards.length && block.depth <= block.guards[block.guards.length - 1]) block.guards.pop();
      if (i > block.start && block.depth <= 0) {
        if (block.guarded > 0 && block.top === 0) {
          console.log(`${f}:${block.start + 1}  ${block.name}  (guarded=${block.guarded} top=0)`);
        }
        block = null;
      }
    }
  }
}
EOF
