const DISCOVERED = /readdirSync|globSync|ls-files|discoverPacks|packsWithProse|discoverTasks|readdir|walk|\.md'\)\)|entries\(|Object\.keys/;
const out = [];
for (const f of files) {
  const src = readFileSync('/home/user/Claudinite/' + f, 'utf8');
  const lines = src.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^(\s*)for\s*\(const\s+(\[?[^)]+?)\s+of\s+(.+?)\)\s*\{\s*$/);
    if (!m) continue;
    const [, ind, vars, srcExpr] = m;
    // is the iterated set discovered rather than a literal array?
    const literal = /^\[/.test(srcExpr.trim());
    let discovered = DISCOVERED.test(srcExpr);
    if (!discovered && !literal) {
      // resolve a simple identifier back to its definition in this file
      const id = srcExpr.trim().match(/^([A-Za-z_$][\w$]*)/);
      if (id) { const def = src.match(new RegExp(`(?:const|let)\\s+${id[1]}\\s*=([^;]*);`, 's')); if (def && DISCOVERED.test(def[1])) discovered = true; }
