      const names = msg && varNames.some((v) => new RegExp(`\\b${v}\\b`).test(msg[1]));
      if (!names) out.push(`${f}:${i + 1 + k + 1}  over ${srcExpr.slice(0, 50)}  ::  ${call.trim().slice(0, 110)}`);
    }
