// "Test via public APIs": an export that ONLY tests import is a seam widened for
// testing — the test pins an implementation detail no caller depends on.
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
const R = '/home/user/Claudinite/';
const all = execSync("git ls-files '*.mjs'", { cwd: R }).toString().trim().split('\n');
const tests = all.filter((f) => f.endsWith('.test.mjs'));
const prod = all.filter((f) => !f.endsWith('.test.mjs'));
const exportsOf = new Map();   // file -> Set(named exports)
for (const f of prod) {
  const src = readFileSync(R + f, 'utf8');
  const s = new Set();
  for (const m of src.matchAll(/^export\s+(?:async\s+)?(?:function|const|let|class)\s+([A-Za-z_$][\w$]*)/gm)) s.add(m[1]);
  for (const m of src.matchAll(/^export\s*\{([^}]*)\}/gm)) for (const p of m[1].split(',')) { const n = p.trim().split(/\s+as\s+/).pop().trim(); if (n) s.add(n); }
  if (s.size) exportsOf.set(f, s);
}
const importedBy = new Map(); // name -> {prod:Set, test:Set}
for (const f of all) {
  const src = readFileSync(R + f, 'utf8');
  for (const m of src.matchAll(/import\s*\{([^}]*)\}\s*from\s*['"]([^'"]+)['"]/g)) {
    for (const p of m[1].split(',')) {
      const n = p.trim().split(/\s+as\s+/)[0].trim();
      if (!n) continue;
      if (!importedBy.has(n)) importedBy.set(n, { prod: new Set(), test: new Set() });
      importedBy.get(n)[f.endsWith('.test.mjs') ? 'test' : 'prod'].add(f);
    }
  }
}
const rows = [];
for (const [f, names] of exportsOf) for (const n of names) {
  const u = importedBy.get(n);
  if (!u) continue;
  if (u.test.size > 0 && u.prod.size === 0) rows.push(`${f}  ${n}  (imported by ${u.test.size} test file${u.test.size > 1 ? 's' : ''}, 0 production)`);
}
console.log(rows.sort().join('\n'));
console.error('total ' + rows.length);
EOF
