// Shape: the test reads a production module's TEXT and asserts an identifier
// appears in it. A rename that touches every call site still fails this.
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
const R = '/home/user/Claudinite/';
const files = execSync("git ls-files '*.test.mjs'", { cwd: R }).toString().trim().split('\n');
for (const f of files) {
  const lines = readFileSync(R + f, 'utf8').split('\n');
  // does this file read production source text at all?
  const readsSrc = lines.some((l) => /readFileSync\(.*\.mjs['"`)]/.test(l) || /readFileSync\(.*\.yml/.test(l));
  if (!readsSrc) continue;
  for (let i = 0; i < lines.length; i++) {
    const L = lines[i];
    if (!/assert\.(ok|match|doesNotMatch|equal)\(/.test(L)) continue;
    // an assertion naming a JS identifier-ish token in a string/regex
