### bootstrap.test.mjs 130-150
// script) reached the owner as a line in a PR body, if at all.
test('the report hands over the executor secret in every adoption, and the web Setup script wherever that pack is on', () => {
  const root = freshRepo();
  const out = run(root, '--packs', 'product-wiki');

  const block = out.slice(out.indexOf('\nHANDOVER'), out.indexOf('\nNEXT:'));
  assert.ok(block.startsWith('\nHANDOVER'), `report carries a HANDOVER block:\n${out}`);
  assert.match(block, /file them as ONE issue/, 'the block says where the steps go');
  assert.match(block, /CCR_ROUTINE_TOKEN/, 'core hands over the executor token secret');
  // Seeded by default, so its step is here without anyone asking for the pack.
  assert.match(block, /Setup script/, 'the web pack hands over its environment Setup script');
  for (const step of block.split('\n').filter((l) => l.startsWith('  [ ] '))) {
    assert.ok(step.length > 40, `a hand-over step says what it is: ${step}`);
  }

  // The routine itself is NOT in there: creating it is the adopting session's
  // work, and the NEXT line has to say so before the commit rather than after.
  assert.doesNotMatch(block, /create the executor routine/i);
  const next = out.slice(out.indexOf('\nNEXT:'));
  assert.match(next, /create the executor routine[\s\S]*before the commit/i, `NEXT orders the routine before the commit:\n${next}`);
});

### scenarios.test.mjs 1322-1340
  await sim.run('2026-08-12T00:00Z', '2026-08-12T08:00Z'); // no resume in this window

  // suspension gates STARTS, not running work: an in-flight run may still finish
  // its item after the hold, but nothing NEW is ever picked
  assert.ok(sim.log.some((e) => e.kind === 'close' && e.t < AT), 'the morning had started');
  assert.equal(sim.log.filter((e) => e.kind === 'evaluate' && e.t >= AT).length, 0, 'no evaluation after the hold');
  const pickedBefore = new Set(sim.log.filter((e) => e.kind === 'evaluate' && e.t < AT).map((e) => e.issue));
  for (const c of sim.log.filter((e) => e.kind === 'close')) {
    assert.ok(pickedBefore.has(c.issue), `#${c.issue} closed post-hold without a pre-hold evaluation`);
  }
  // the parked runs are visible, workflow by workflow
  const skips = sim.log.filter((e) => e.kind === 'suspended-skip');
  assert.ok(skips.some((e) => e.workflow === 'executor'), 'the in-flight drain parked between items');
  assert.ok(skips.filter((e) => e.workflow === 'scheduler-run').length >= 3, 'every cron fire exited at start');
  // and the queue is frozen, not lost: every never-picked item still sits ready
  const openReady = sim.issues.filter((i) => !i.seeded && i.state === 'open');
  assert.equal(openReady.length, 5 - pickedBefore.size, 'unpicked items all survived the hold');
  for (const it of openReady) assert.ok(it.labels.has(READY), `#${it.number} froze as ready`);
});

### scenarios.test.mjs 1388-1400

  // no instant ever had two same-title items in execution
  const twinEvals = sim.log.filter((e) => e.kind === 'evaluate' && e.task === 'fleet/fleet-baseline');
  const times = twinEvals.map((e) => e.t);
  assert.equal(new Set(times).size, times.length, 'the twins were never evaluated at the same instant');
  // and BOTH still converged — a reverted or lost claim is re-claimed in a fresh
  // episode (F18) and simply waits its turn
  for (const it of sim.issues.filter((i) => !i.seeded)) {
    assert.equal(it.state, 'closed', `#${it.number} converged`);
    assert.equal(it.outcome, 'done', `#${it.number} ran — an empty expression holds at pick`);
  }
});

